import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"Dragonfly","description":"","frontmatter":{},"headers":[],"relativePath":"guide/redis-tm-compatibility/dragonfly.md","filePath":"guide/redis-tm-compatibility/dragonfly.md","lastUpdated":1700148907000}`),a={name:`guide/redis-tm-compatibility/dragonfly.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="dragonfly" tabindex="-1">Dragonfly <a class="header-anchor" href="#dragonfly" aria-label="Permalink to “Dragonfly”">​</a></h1><p><a href="https://www.dragonflydb.io/" target="_blank" rel="noreferrer">Dragonfly</a> offers a drop-in replacement for Redis™, boasting a much faster and more memory-efficient implementation of several data structures used by BullMQ. It also enables the utilization of all available cores in your CPUs. Check <a href="https://bullmq.io/news/101023/dragonfly-compatibility/" target="_blank" rel="noreferrer">this article</a> for some performance results.</p><p>To fully leverage Dragonfly&#39;s capabilities, specific steps are necessary. Primarily, you should name your queues using curly braces. This naming convention allows Dragonfly to assign a thread to each queue. For instance, if your queue is named <code>myqueue,</code>rename it to <code>{myqueue}</code>.</p><p>If you manage multiple queues, this approach enables you to allocate different CPU cores to each queue, significantly enhancing performance. Even with a single queue, you can still exploit multi-core advantages in some cases. Consider splitting your queue into multiple ones, like<code>{myqueue-1}</code>, <code>{myqueue-2}</code>, etc., and distribute jobs randomly or using a round-robin method.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Be aware that certain features like priorities and rate-limiting might not function across multiple queues. Your specific requirements will determine whether you can divide a single queue in this manner.</p></div><p>For comprehensive instructions and the necessary flags to optimize your Dragonfly instance for BullMQ, please consult the <a href="https://www.dragonflydb.io/docs/integrations/bullmq" target="_blank" rel="noreferrer">official integration guide</a>.</p>`,6)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};